      "path": ".github/workflows/linkcheck.yml",
      "content": "name: linkcheck\n\non:\n  schedule:\n    - cron: '0 3 * * 1'   # 每周一 03:00 UTC\n  workflow_dispatch:        # 支持手动触发\n\npermissions:\n  contents: read\n  issues: write\n\njobs:\n  linkcheck:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Check links\n        id: lychee\n        uses: lycheeverse/lychee-action@v2\n        with:\n          update-existing: true\n          args: --no-progress --accept 200,201,204,301,302,304,307,308 --timeout 20 --max-redirects 3 --exclude 'img\\.shields\\.io' '**/*.md'\n          fail: true\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n\n      - name: Open issue on dead links\n        if: failure()\n        uses: peter-evans/create-issue-from-file@v5\n        with:\n          title: \"🔗 死链检测报告（自动）\"\n          content-filepath: ./lychee/out.md\n          labels: |\n            report\n            automated\n"
